package main

import "fmt"

func changeArray(values [2]int) {
	values[0] = 7
}

func changeElement(values []int) {
	values[0] = 7
}

func showLocalLength(values []int) {
	values = values[:1]
	fmt.Println("inside length:", len(values))
}

func add(values []int, value int) []int {
	return append(values, value)
}

func main() {
	array := [2]int{1, 2}
	slice := []int{1, 2}

	changeArray(array)
	changeElement(slice)
	showLocalLength(slice)
	fmt.Println("caller values:", array, slice, len(slice))

	slice = add(slice, 9)
	fmt.Println("after returned append:", slice)
}
