package main

import "fmt"

type TraceID [16]byte

func sameTrace(left, right TraceID) bool {
	return left == right
}

func total(values []int) int {
	sum := 0
	for _, value := range values {
		sum += value
	}
	return sum
}

func main() {
	first := TraceID{0x7f}
	second := first
	batch := make([]int, 0, 4)
	batch = append(batch, 2, 3, 5)

	fmt.Println("same trace:", sameTrace(first, second))
	fmt.Println("batch total:", total(batch))
}
